from fractions import Fraction
from itertools import product

import ledger

declared = [\" Straße \", \"ΟΣ\", \"Zoë\", \"Åse\"]
aliases = [\"STRASSE\", \"οσ\", \"ZOË\", \"ÅSE\"]
names = [name.strip().lower() for name in declared]


def group(expenses):
    return {\"currency\": \"eUr\", \"members\": declared, \"expenses\": expenses}


def money(cents):
    return f\"{cents // 100}.{cents % 100:02}\"


def reference_settle(original):
    net = original.copy()
    transfers = []
    while any(net.values()):
        debtor = min(net, key=lambda name: (net[name], name))
        creditor = min(net, key=lambda name: (-net[name], name))
        cents = min(-net[debtor], net[creditor])
        net[debtor] += cents
        net[creditor] -= cents
        transfers.append((debtor, creditor, cents))
    return transfers


def assert_results(expenses, expected):
    assert ledger.balances(group(expenses)) == expected, (expenses, expected)
    assert ledger.settle(group(expenses)) == reference_settle(expected), (expenses, expected)


settlement_cases = 0
for cents in product(range(-3, 4), repeat=len(names)):
    if sum(cents) "'!= 0:
        continue
    expected = dict(zip(names, cents))
    expenses = []
    # Independently build expenses that realize the starting balances.
    pending = [[alias, -value] for alias, value in zip(aliases, cents) if value < 0]
    for alias, value in zip(aliases, cents):
        if value <= 0:
            continue
        amounts = {}
        remaining_credit = value
        for debt in pending:
            share = min(debt[1], remaining_credit)
            if share:
                amounts[debt[0]] = money(share)
                debt[1] -= share
                remaining_credit -= share
        expenses.append({"id": alias, "payer": alias, "amount": money(value),
                         "split": {"type": "exact", "amounts": amounts}})
    assert_results(expenses, expected)
    settlement_cases += 1


def check_rounding(cents, fractions, split):
    shares = {name: int(fraction) for name, fraction in fractions.items()}
    order = sorted(shares, key=lambda name: (shares[name] - fractions[name], name))
    for name in order[:cents - sum(shares.values())]:
        shares[name] += 1
    expected = {name: -shares.get(name, 0) for name in names}
    expected[names[-1]] += cents
    assert_results([{"id": "expense", "payer": aliases[-1], "amount": money(cents), "split": split}], expected)


rounding_cases = 0
weights = (1, 2, 499, 1000, 3333, 3334, 4999, 5000, 9998)
for cents in range(1, 61):
    check_rounding(cents, dict.fromkeys(names, Fraction(cents, 4)), {"type": "equal"})
    rounding_cases += 1
    for first, second in product(weights, repeat=2):
        third = 10000 - first - second
        if third <= 0:
            continue
        percentages = (first, second, third)
        split = {"type": "percent", "percents": {alias: money(weight) for alias, weight in zip(aliases, percentages)}}
        fractions = {name: Fraction(cents * weight, 10000) for name, weight in zip(names, percentages)}
        check_rounding(cents, fractions, split)
        rounding_cases += 1

print(f"{settlement_cases} settlement configurations and {rounding_cases} rounding cases matched independent references.")
